-- =============================================================================
-- Migration: Replace centroid Voronoi with arrondissement-polygon zone lookup
-- Description: Loads Montréal's 34 administrative boundaries (arrondissements
--              + reconstituted "villes liées") as polygons and rewrites
--              derive_zone_from_location() to use ST_Contains() against them.
--              Polygons sourced from Ville de Montréal open data
--              (limites-administratives-agglomeration, WGS 84) and simplified
--              to ~50 m tolerance to keep this migration small (~45 KB) while
--              preserving zone-boundary fidelity. Source CC-BY 4.0.
-- =============================================================================

-- =============================================================================
-- STEP 1: Borough table
-- =============================================================================
CREATE TABLE IF NOT EXISTS public.montreal_borough (
  name TEXT PRIMARY KEY,
  zone TEXT NOT NULL CHECK (zone IN ('ouest_ile','ouest','centre','nord','est')),
  geom extensions.geometry(MultiPolygon, 4326) NOT NULL,
  created_at TIMESTAMPTZ DEFAULT NOW()
);

CREATE INDEX IF NOT EXISTS idx_montreal_borough_geom
  ON public.montreal_borough USING GIST (geom);

CREATE INDEX IF NOT EXISTS idx_montreal_borough_zone
  ON public.montreal_borough (zone);

COMMENT ON TABLE public.montreal_borough IS
'Montréal arrondissements and "villes liées" with their GMA zone. Sourced from Ville de Montréal open data (limites-administratives-agglomeration, WGS 84) under CC-BY 4.0.';

-- Idempotent reseed: clear the table so re-runs replace polygons cleanly.
TRUNCATE public.montreal_borough;

-- =============================================================================
-- STEP 2: Polygon inserts (34 boroughs)
-- =============================================================================
