-- Wrap geometries in extensions schema for consistency (ST_GeomFromText emits
-- the same SRID; this is just a no-op cast to the typed column).

-- =============================================================================
-- STEP 3: Replace derive_zone_from_location to use polygon containment
-- =============================================================================
CREATE OR REPLACE FUNCTION public.derive_zone_from_location(
  p_location extensions.geography
)
RETURNS TEXT
LANGUAGE sql
STABLE
AS $$
  SELECT zone
  FROM public.montreal_borough
  WHERE p_location IS NOT NULL
    AND extensions.ST_Contains(geom, p_location::extensions.geometry)
  LIMIT 1;
$$;

COMMENT ON FUNCTION public.derive_zone_from_location IS
'Returns the GMA zone (ouest_ile/ouest/centre/nord/est) that contains the given location. Uses polygon containment against montreal_borough; returns NULL when the point is outside the agglomeration of Montréal.';

-- =============================================================================
-- STEP 4: Reconcile existing memberships with the new zone resolution
-- Drop network_member rows whose network.zone no longer matches the player's
-- newly-resolved zone, then re-run the backfill so every onboarded player ends
-- up in the correct (zone × sport × skill_level) communities.
-- =============================================================================
DO $$
DECLARE
  v_community_type_id UUID;
  v_deleted INTEGER;
  v_inserted INTEGER;
BEGIN
  SELECT id INTO v_community_type_id
  FROM public.network_type WHERE name = 'community';

  WITH stale AS (
    SELECT nm.network_id, nm.player_id
    FROM public.network_member nm
    JOIN public.network n ON n.id = nm.network_id
    JOIN public.player p ON p.id = nm.player_id
    WHERE n.zone IS NOT NULL
      AND n.zone IS DISTINCT FROM public.derive_zone_from_location(p.location)
  ),
  deleted AS (
    DELETE FROM public.network_member nm
    USING stale s
    WHERE nm.network_id = s.network_id AND nm.player_id = s.player_id
    RETURNING 1
  )
  SELECT count(*) INTO v_deleted FROM deleted;

  WITH player_zone_skill AS (
    SELECT
      p.id AS player_id,
      public.derive_zone_from_location(p.location) AS zone,
      rsy.sport_id,
      CASE WHEN rs.skill_level = 'professional' THEN 'advanced'::skill_level
           ELSE rs.skill_level END AS skill_level
    FROM public.profile pr
    JOIN public.player p ON p.id = pr.id
    JOIN public.player_rating_score prs ON prs.player_id = p.id
    JOIN public.rating_score rs ON rs.id = prs.rating_score_id
    JOIN public.rating_system rsy ON rsy.id = rs.rating_system_id
    JOIN public.player_sport ps ON ps.player_id = p.id AND ps.sport_id = rsy.sport_id
    WHERE pr.onboarding_completed = TRUE
  ),
  inserted AS (
    INSERT INTO public.network_member (
      network_id, player_id, status, joined_at, request_type, role
    )
    SELECT
      n.id, pzs.player_id, 'active'::network_member_status, NOW(),
      'direct_add'::network_member_request_type, 'member'
    FROM player_zone_skill pzs
    JOIN public.network n
      ON n.network_type_id = v_community_type_id
     AND n.zone = pzs.zone
     AND n.sport_id = pzs.sport_id
     AND n.skill_level = pzs.skill_level
     AND n.archived_at IS NULL
    WHERE pzs.zone IS NOT NULL AND pzs.skill_level IS NOT NULL
    ON CONFLICT (network_id, player_id) DO NOTHING
    RETURNING 1
  )
  SELECT count(*) INTO v_inserted FROM inserted;

  RAISE NOTICE 'Polygon reconcile: % stale memberships removed, % new memberships inserted',
    v_deleted, v_inserted;
END
$$;

-- =============================================================================
-- STEP 5: RLS - the borough table is reference data, world-readable
-- =============================================================================
ALTER TABLE public.montreal_borough ENABLE ROW LEVEL SECURITY;

DROP POLICY IF EXISTS "Anyone can view montreal boroughs" ON public.montreal_borough;
CREATE POLICY "Anyone can view montreal boroughs"
  ON public.montreal_borough FOR SELECT
  TO anon, authenticated
  USING (true);
